package com.ethk3.novaonepro.strategyv2;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class RepairCalibrationRoleR30Test {
 @Test public void allFormalLabelsCanChangeWithoutChangingAnyFit(){List<CalibrationRowsR27.Row>a=R30CalibrationTest.rows(),b=new ArrayList<>();for(CalibrationRowsR27.Row r:a)b.add(new CalibrationRowsR27.Row(r.issue,r.source,r.frozenAt,r.openTime,r.score,r.source.equals("FUTURE")?1-r.hit:r.hit,r.position,true,true,r.ordinal));CalibrationRowsR27.Result x=CalibrationRowsR27.fitRolling(a),y=CalibrationRowsR27.fitRolling(b);assertEquals("REPLAY",x.fitSource);assertEquals(500,x.validationRows);for(int i=0;i<x.validationRows;i++){assertEquals(x.evaluations.get(i).fitHash,y.evaluations.get(i).fitHash);assertEquals(x.evaluations.get(i).probability,y.evaluations.get(i).probability,0);}assertNotEquals(x.ece,y.ece,1e-4);assertEquals(0L,x.quality.get("formalLabelsUsedForFit"));}
 @Test public void formalOnlyNeverFitsAndInvalidArraysDoNotBecomeHealthy(){List<CalibrationRowsR27.Row>r=R30CalibrationTest.rows().subList(150,650);assertEquals(0,CalibrationRowsR27.fitRolling(r).validationRows);assertNull(CalibrationRowsR27.fitRolling(r).quality.get("q05Pass"));assertEquals("INVALID_INPUT",CalibrationR30.evaluate(new double[]{Double.NaN},new int[]{1},1,10,0,1).get("status"));assertEquals("INVALID_INPUT",CalibrationR30.evaluate(new double[1],new int[]{2},2,10,0,1).get("status"));}
 @Test public void q05UsesTheOriginalPredrawActCondition(){List<CalibrationRowsR27.Row> rows=new ArrayList<>();for(CalibrationRowsR27.Row r:R30CalibrationTest.rows())rows.add(new CalibrationRowsR27.Row(r.issue,r.source,r.frozenAt,r.openTime,r.score,r.hit,r.position,true,true,r.ordinal,!r.source.equals("FUTURE")||r.ordinal%2==0));CalibrationRowsR27.Result a=CalibrationRowsR27.fitRolling(rows);assertEquals(250,a.validationRows);assertEquals(250,a.excludedNonAct);assertEquals("PREDECLARED_ACT_EQUALS_1",a.quality.get("evaluationCondition"));for(CalibrationRowsR27.Evaluation e:a.evaluations)assertEquals(0,e.ordinal%2);}
}
